START TRANSACTION;
CREATE TABLE course_deletion_requests (
    "RequestID" bigint GENERATED BY DEFAULT AS IDENTITY,
    "CourseID" integer NOT NULL,
    "CourseTitle" character varying(255) NOT NULL,
    "InstructorID" integer NOT NULL,
    "InstructorName" character varying(255) NOT NULL,
    "Reason" character varying(1000) NOT NULL,
    "Status" character varying(20) NOT NULL DEFAULT 'PENDING',
    "RequestedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "ReviewedByID" integer,
    "ReviewedAt" timestamp with time zone,
    "AdminNote" character varying(1000),
    CONSTRAINT "PK_course_deletion_requests" PRIMARY KEY ("RequestID")
);

CREATE UNIQUE INDEX "IX_course_deletion_requests_CourseID" ON course_deletion_requests ("CourseID") WHERE "Status" = 'PENDING';

CREATE INDEX "IX_course_deletion_requests_Status_RequestedAt" ON course_deletion_requests ("Status", "RequestedAt");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261106152223_AddCourseDeletionRequests', '9.0.0');

CREATE TABLE ai_pronunciation_feedbacks (
    "FeedbackId" integer GENERATED BY DEFAULT AS IDENTITY,
    "SubmissionId" integer NOT NULL,
    "LearnerId" integer NOT NULL,
    "ModelVersion" character varying(50) NOT NULL,
    "CheckpointEpoch" integer NOT NULL,
    "LLMProvider" character varying(100) NOT NULL,
    "LLMModel" character varying(100) NOT NULL,
    "PredictionJson" text NOT NULL,
    "FeedbackJson" text NOT NULL,
    "Summary" text NOT NULL,
    "ExpectedText" text,
    "TranscriptText" text,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_ai_pronunciation_feedbacks" PRIMARY KEY ("FeedbackId"),
    CONSTRAINT "FK_ai_pronunciation_feedbacks_speaking_submissions_SubmissionId" FOREIGN KEY ("SubmissionId") REFERENCES speaking_submissions ("SubmissionID") ON DELETE CASCADE,
    CONSTRAINT "FK_ai_pronunciation_feedbacks_users_LearnerId" FOREIGN KEY ("LearnerId") REFERENCES users ("UserID") ON DELETE RESTRICT
);

CREATE INDEX "IX_ai_pronunciation_feedbacks_LearnerId" ON ai_pronunciation_feedbacks ("LearnerId");

CREATE UNIQUE INDEX "IX_ai_pronunciation_feedbacks_SubmissionId_LearnerId" ON ai_pronunciation_feedbacks ("SubmissionId", "LearnerId");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20261108075509_AddAIPronunciationFeedbackTable', '9.0.0');

